import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.Objects;

public class StreamPipelineProcessor {

    /**
     * Reads a UTF-8 encoded text file, converts all text to uppercase, and writes it to an output file.
     * Demonstrates the decorator pattern, explicit encoding, and modern try-with-resources.
     */
    public void processTextFile(File source, File destination) throws IOException {
        Objects.requireNonNull(source, "Source file cannot be null");
        Objects.requireNonNull(destination, "Destination file cannot be null");

        // Decorator chain: File -> Buffered Byte Stream -> Character Bridge -> Buffered Character Stream
        try (InputStream fis = new FileInputStream(source);
             BufferedInputStream bis = new BufferedInputStream(fis);
             Reader reader = new InputStreamReader(bis, StandardCharsets.UTF_8);
             BufferedReader bufferedReader = new BufferedReader(reader);

             OutputStream fos = new FileOutputStream(destination);
             BufferedOutputStream bos = new BufferedOutputStream(fos);
             Writer writer = new OutputStreamWriter(bos, StandardCharsets.UTF_8);
             BufferedWriter bufferedWriter = new BufferedWriter(writer)) {

            String line;
            while ((line = bufferedReader.readLine()) != null) {
                bufferedWriter.write(line.toUpperCase());
                bufferedWriter.newLine();
            }
            // Flush is implicitly called when BufferedWriter closes, but explicit flush ensures data integrity before exit
            bufferedWriter.flush();
        }
    }
}
